cd /home/one/projects/one/ai-guides/protocols/telegram_bots_guide && python3 - <<'PY'
import re, pathlib, subprocess, concurrent.futures
urls=set()
for p in pathlib.Path('.').glob('*.md'):
    for line in p.read_text().splitlines():
        if line.startswith('- http'):
            for u in re.split(r';\s*', line[2:].strip()):
                u=u.strip().rstrip('.,;')
                if u.startswith(('https://core.telegram.org/','https://github.com/')):
                    urls.add(u)
def check(u):
    r=subprocess.run(['curl','-sS','-L','-o','/dev/null','-w','%{http_code}','--max-time','20',u],capture_output=True,text=True)
    return u,r.stdout.strip()
bad=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=10) as ex:
    for u,c in ex.map(check,sorted(urls)):
        if c!='200': bad.append((u,c))
print(f'canonical URLs: {len(urls)}; bad: {len(bad)}')
for u,c in bad: print(' ',c,u)
